<?php require 'config.php'; $errors=[]; if($_SERVER['REQUEST_METHOD']==='POST'){ $name=trim($_POST['full_name']??'');$email=trim($_POST['email']??'');$sid=trim($_POST['student_id']??'');$course=trim($_POST['course']??'');$pass=$_POST['password']??'';$confirm=$_POST['confirm_password']??''; if(!$name||!$email||!$sid||!$course||!$pass)$errors[]='All fields are required.'; if(!filter_var($email,FILTER_VALIDATE_EMAIL))$errors[]='Enter a valid email.'; if($pass!==$confirm)$errors[]='Passwords do not match.'; if(!$errors){$q=$db->prepare('SELECT id FROM students WHERE email=? OR student_id=?');$q->bind_param('ss',$email,$sid);$q->execute();if($q->get_result()->num_rows)$errors[]='Email or student ID already exists.';else{$h=password_hash($pass,PASSWORD_DEFAULT);$q=$db->prepare('INSERT INTO students(student_id,full_name,email,course,password) VALUES(?,?,?,?,?)');$q->bind_param('sssss',$sid,$name,$email,$course,$h);$q->execute();header('Location: login.php?registered=1');exit;}}} ?><!doctype html><html><head><title>Register</title><link rel="stylesheet" href="style.css"></head><body><main class="card"><h1>Register</h1><?php foreach($errors as $x): ?><p class="error"><?=e($x)?></p><?php endforeach; ?><form method="post"><input name="full_name" placeholder="Full name" required><input name="email" type="email" placeholder="Email" required><input name="student_id" placeholder="Student ID" required><input name="course" placeholder="Course" required><input name="password" type="password" placeholder="Password" required><input name="confirm_password" type="password" placeholder="Confirm password" required><button>Register</button></form><a href="login.php">Already registered?</a></main></body></html>
